    cid = (chat_id or current_chat_id() or "default").strip() or "default"
    # Keep pid filenames filesystem-safe and stable per chat id.
    safe = re.sub(r'[^\\w\\u4e00-\\u9fff.-]+', "_", cid).strip("._") or "default"
