import re, py_compile, subprocess, tempfile, os

root = Path(r'C:\Users\12159\Desktop\ai_exec')

old = '''function syncRunningFromCache(){
  const row=(chatsCache||[]).find(c=>c && String(c.id)===String(activeChatId));
  const run=!!(row && row.running);
  if(isRunning!==run){
    isRunning=run;
    if(!run && phaseLabel==='等待 AI') phaseLabel='空闲';
    if(run && (!phaseLabel || phaseLabel==='空闲')) phaseLabel='运行中';
    setRunningUi();
  }else{
    setRunningUi();
  }
}'''

new = '''function syncRunningFromCache(){
  // Only UPGRADE active running state from the chat list (e.g. switch onto a
  // background task). Downgrades are owned by /api/state polling so a slightly
  // stale chats list cannot flip a just-finished task back to "运行中".
  const row=(chatsCache||[]).find(c=>c && String(c.id)===String(activeChatId));
  const run=!!(row && row.running);
  if(run && !isRunning){
    isRunning=true;
    if(!phaseLabel || phaseLabel==='空闲') phaseLabel='运行中';
    setRunningUi();
  }
}'''

for name in ['responses','chat_completions','messages']:
    p = root/name/'viewer.py'
    text = p.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'{name} sync func missing')
    text = text.replace(old, new, 1)
    p.write_text(text, encoding='utf-8')
    py_compile.compile(str(p), doraise=True)
    # js check last app block
    blocks = re.findall(r'<script(?![^>]*src=)[^>]*>(.*?)</script>', text, flags=re.S|re.I)
    with tempfile.NamedTemporaryFile('w', suffix='.js', delete=False, encoding='utf-8') as f:
        f.write(blocks[-1]); path=f.name
    r = subprocess.run(['node','--check',path], capture_output=True, text=True)
    os.unlink(path)
    if r.returncode!=0:
        raise SystemExit(r.stderr)
    print(name, 'OK')
print('done')
"}

